/* part:page.style.kit.combobox */
/* Kit css: Combobox    kit version 0.1.0    pairs with kit/combobox.js
   .kit-cb the root (position: relative; the list opens inside it, below or, with .kit-cb-up, above); .kit-cb-field the bordered box with chips, input and buttons
   .kit-cb-pop the list frame; .kit-cb-opt an option (.kit-cb-on is a chosen one and carries a check, .kit-cb-act is the active one with a left bar, so neither rides on colour alone)
   .kit-cb-create the "Create" option; .kit-cb-grp a group head; .kit-cb-note the empty, loading or error line; .kit-cb-chip a chosen value in multiple mode
   Needs from the board: --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --danger --f-ui; --seam --focus --shadow --radius optional. */
.kit-cb { position: relative; min-width: 0; font: 15px/1.4 var(--f-ui); color: var(--ink); }
.kit-cb-field { display: flex; flex-wrap: wrap; align-items: center; gap: 4px; min-height: 40px; box-sizing: border-box; padding-block: 3px; padding-inline: 10px 4px;
  background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); cursor: text; }
.kit-cb-field:focus-within { outline: 2px solid var(--focus, var(--accent)); outline-offset: 1px; }
.kit-cb-in { flex: 1 1 9ch; min-width: 9ch; box-sizing: border-box; height: 32px; padding: 0; border: 0; background: transparent; color: var(--ink); font: 16px/1.4 var(--f-ui); }
.kit-cb-in:focus-visible { outline: none; }
.kit-cb-in::placeholder { color: var(--ink-2); opacity: 1; }
.kit-cb-clear, .kit-cb-chev, .kit-cb-x { flex: none; display: inline-flex; align-items: center; justify-content: center; width: 28px; height: 28px; padding: 0; border: 0;
  border-radius: calc(var(--radius, 6px) - 1px); background: transparent; color: var(--ink-2); font: 18px/1 var(--f-ui); cursor: pointer; }
.kit-cb-clear:hover, .kit-cb-chev:hover, .kit-cb-x:hover { background: var(--sunk); color: var(--ink); }
.kit-cb-chev::before { content: ""; width: 7px; height: 7px; margin-top: -3px; border: solid currentColor; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.kit-cb-open .kit-cb-chev::before { margin-top: 3px; transform: rotate(-135deg); }
.kit-cb:not(.kit-cb-has) .kit-cb-clear { visibility: hidden; }
.kit-cb-chip { display: inline-flex; align-items: center; max-width: 100%; min-height: 28px; padding-inline-start: 8px; background: var(--sunk); border: 1px solid var(--rule); border-radius: 14px; font-size: 14px; }
.kit-cb-chip-t { min-width: 0; overflow-wrap: anywhere; }
.kit-cb-x { width: 24px; height: 24px; margin: 1px; margin-inline-start: 2px; border-radius: 12px; font-size: 16px; }
.kit-cb-x:focus-visible, .kit-cb-clear:focus-visible { outline: 2px solid var(--focus, var(--accent)); outline-offset: 0; }
.kit-cb-pop { position: absolute; z-index: 60; left: 0; right: 0; top: calc(100% + 4px); box-sizing: border-box; max-height: 300px; overflow-y: auto; overscroll-behavior: contain;
  background: var(--panel); border: 1px solid var(--rule); border-radius: var(--radius, 6px); box-shadow: var(--shadow, 0 12px 32px color-mix(in srgb, var(--ink) 25%, transparent)); }
.kit-cb-pop[hidden] { display: none; }
.kit-cb-up { top: auto; bottom: calc(100% + 4px); }
.kit-cb-busy .kit-cb-list { opacity: .55; }
.kit-cb-note { padding: 10px 12px; color: var(--ink-2); }
.kit-cb-note[hidden] { display: none; }
.kit-cb-err { color: var(--danger); }
.kit-cb-grp { padding: 8px 12px 2px; font: 600 12px/1.4 var(--f-ui); letter-spacing: .04em; text-transform: uppercase; color: var(--ink-2); }
.kit-cb-opt { display: flex; align-items: baseline; gap: 10px; min-height: 24px; padding-block: 7px; padding-inline: 9px 12px; border-inline-start: 3px solid transparent; cursor: pointer; }
.kit-cb-opt + .kit-cb-opt { border-top: 1px solid var(--rule-2); }
.kit-cb-act { background: var(--sunk); border-inline-start-color: var(--seam, var(--accent)); }
.kit-cb-t { flex: 1 1 auto; min-width: 0; overflow-wrap: anywhere; }
.kit-cb-t mark { background: transparent; color: inherit; font-weight: 700; text-decoration: underline; text-decoration-thickness: 2px; text-underline-offset: 3px; text-decoration-color: var(--seam, var(--accent)); }
.kit-cb-hint { flex: none; font-size: 12px; color: var(--ink-2); }
.kit-cb-on::after { content: "✓"; flex: none; color: var(--accent); font-weight: 700; }
.kit-cb-opt[aria-disabled="true"] { color: var(--ink-3); cursor: default; }
.kit-cb-create { font-style: italic; }
.kit-cb-live { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
@media (prefers-reduced-motion: no-preference) { .kit-cb-chev::before { transition: transform .12s ease-out, margin-top .12s ease-out; } }
/* /part:page.style.kit.combobox */

/**
 * Combobox
 * Kit.combobox.mount(el, opts) builds a type-to-filter field in el: one choice or several (chips), from an array or from an async source, with optional groups, match highlighting and "create new". It is the WAI-ARIA APG list-autocomplete combobox: the input keeps focus, the list is a listbox, the active option is named by aria-activedescendant and a live line says the result count.
 *
 * What it is: the pick-one-of-many field for lists too long for a select: people, tags, places, accounts. Typing filters (case and accent blind; matches at the start of the label or of a word rank first), the chosen text is highlighted,
 * and an async source is asked after a pause, with the request before it cancelled. Values are strings (a number value becomes its string); the kit stores nothing and never touches the page's data.
 * ARIA: single choice puts aria-selected on the active option (the APG list-autocomplete way; the chosen one carries a check mark); multiple puts it on every chosen option, with aria-multiselectable.
 * API (small and stable):
 *   Kit.combobox.mount(el, opts) -> box       builds .kit-cb in el
 *   opts.items         [string | {value, label, group?, hint?, disabled?}]   the options (sync); string is its own value and label; group makes a headed section
 *   opts.source        (query, {signal}) -> Promise<items>   async options instead of items; called when the list opens and after each pause in typing; signal aborts when superseded, closed or destroyed
 *   opts.multiple      false (default): one value, shown in the input. true: chips, Backspace removes the last
 *   opts.value         value (single) or [values] (multiple) to start with; an item object works too, which an async source needs for the label
 *   opts.allowCreate   true: when no option matches the text exactly, a last option "Create “text”" adds it as {value: text, label: text, created: true}
 *   opts.onChange      (value, items) => void   value is a string or null (single) or an array (multiple); items are the chosen option objects. Not called by setValue.
 *   opts.label, id, placeholder, debounce (ms, default 200), clearable (single, default true), text {empty, loading, error, create(q), count(n), added(l), removed(l), remove(l), show, clear}
 *   box.getValue() / box.getItems() / box.setValue(v) / box.setItems(items) / box.open() / box.close() / box.focus() / box.destroy()   box.input is the input, box.el the root
 * Keys (APG): Down opens and moves to the next option (a single choice opens on the chosen one, else the first), Up opens at the last, Alt+Down opens without moving, Enter picks the active option, Escape closes and puts the chosen text back (when closed it is left to the page),
 * Left, Right, Home and End go back to the text (no active option). Single choice: typing highlights the first match, and Tab or leaving the field accepts it (APG automatic selection); Create is never accepted that way. Multiple: Backspace on empty text removes the last chip; Left at the start of the empty text walks the chips, Backspace or Delete removes one.
 * Give the field a name with opts.label, or with a visible <label for=id> and opts.id. It needs room: the list opens below (above when the page is short there) and is clipped by an ancestor with overflow:hidden.
 * Leaves out: virtual scrolling or paging (hand it the page of results the source returns), the form field's own label and validation (the page supplies them), and a list that escapes an overflow:hidden ancestor.
 *
 * @id        kit.combobox
 * @kind      component
 * @group     Kit
 * @status    new
 * @version   0.1.0
 * @updated   2026-11-22
 * @summary   A type-to-filter field for one or many values: array or async source with debounce and cancel, groups, match highlight, create new, chips. WAI-ARIA list-autocomplete combobox; keyboard, pointer and touch.
 * @tags      combobox, autocomplete, select, multiselect, typeahead, search, chips, tags, async, aria, keyboard, form
 * @requires  none
 * @files     kit/combobox.css, kit/samples/combobox.json, kit/previews/combobox.js
 * @provides  Kit.combobox.mount
 * @config    Kit.combobox.mount(el, opts) | items or source(query, {signal}), multiple, value, allowCreate, onChange(value, items), label, id, placeholder, debounce, clearable, text
 * @config    box | getValue(), getItems(), setValue(v), setItems(items), open(), close(), focus(), destroy(); input, el
 * @tokens    --panel --sunk --ink --ink-2 --ink-3 --rule --rule-2 --accent --danger --f-ui --seam? --focus? --shadow? --radius?
 * @globals   none
 * @db        none
 * @preview   {"render": "kit.combobox", "samples": ["kit/samples/combobox.json"]}
 */
(function () {
'use strict';
const Kit = window.Kit = window.Kit || { version: '0.1.0' };
let seq = 0;
const TEXT = { empty: 'No matches', loading: 'Loading…', error: 'Could not load. Type to try again.', create: q => 'Create “' + q + '”',
  count: n => n + (n === 1 ? ' result' : ' results'), added: l => l + ' added', removed: l => l + ' removed', remove: l => 'Remove ' + l, show: 'Show options', clear: 'Clear' };
const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt != null) e.textContent = txt; return e; };
const btn = (cls, txt, label) => { const b = el('button', cls, txt); b.type = 'button'; b.tabIndex = -1; b.setAttribute('aria-label', label); return b; };
// fold keeps one char per UTF-16 unit, so an index in the folded text is an index in the label
const f1 = c => { const s = c.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase(); return s.length === 1 ? s : c; };
const fold = s => String(s == null ? '' : s).split('').map(f1).join('');
const def = o => Object.fromEntries(Object.entries(o || {}).filter(e => e[1] !== undefined)); // an undefined option keeps its default
const norm = x => x && typeof x === 'object' ? (typeof x.value === 'string' && x.label != null ? x : { ...x, value: String(x.value), label: x.label == null ? String(x.value) : x.label }) : { value: String(x), label: String(x) };

function rank(items, q) {
  const fq = fold(q);
  if (!fq) return items;
  const out = [];
  items.forEach((it, n) => {
    const fl = fold(it.label), i = fl.indexOf(fq);
    if (i >= 0) out.push([fl === fq ? 0 : i === 0 ? 1 : /[\s\-_/.,(]/.test(fl[i - 1]) ? 2 : 3, n, it]);
  });
  return out.sort((a, b) => a[0] - b[0] || a[1] - b[1]).map(x => x[2]);
}
function mark(node, label, q) {
  const w = fold(q), i = w ? fold(label).indexOf(w) : -1;
  if (i < 0) { node.textContent = label; return; }
  node.append(label.slice(0, i), el('mark', null, label.slice(i, i + w.length)), label.slice(i + w.length));
}

function mount(host, opts = {}) {
  const o = { items: [], source: null, multiple: false, value: null, debounce: 200, allowCreate: false, clearable: true, ...def(opts) };
  const T = { ...TEXT, ...def(opts.text) };
  const id = 'kit-cb-' + (++seq), lc = new AbortController();
  const on = (t, ev, fn) => t.addEventListener(ev, fn, { signal: lc.signal });
  const known = new Map(), reg = l => l.map(norm).map(it => (known.set(it.value, it), it));
  let items = reg(o.items), srcItems = [], sel = [], shown = [], act = -1, nav = 0, want = null, isOpen = false, typed = false, loading = false, failed = false, timer = 0, ctl = null, xy = '';

  const root = el('div', 'kit-cb' + (o.multiple ? ' kit-cb-multi' : ''));
  const field = el('div', 'kit-cb-field');
  const input = el('input', 'kit-cb-in');
  input.type = 'text'; input.id = o.id || id + '-in'; input.autocomplete = 'off'; input.spellcheck = false;
  if (o.placeholder) input.placeholder = o.placeholder;
  if (o.label) input.setAttribute('aria-label', o.label);
  input.setAttribute('role', 'combobox'); input.setAttribute('aria-autocomplete', 'list'); input.setAttribute('aria-expanded', 'false'); input.setAttribute('aria-controls', id + '-list');
  const clear = btn('kit-cb-clear', '×', T.clear), chev = btn('kit-cb-chev', '', T.show);
  field.append(input); if (!o.multiple && o.clearable) field.append(clear); field.append(chev);
  const pop = el('div', 'kit-cb-pop'); pop.hidden = true;
  const note = el('div', 'kit-cb-note'), list = el('div', 'kit-cb-list');
  list.id = id + '-list'; list.setAttribute('role', 'listbox'); list.setAttribute('aria-label', o.label || 'Options'); if (o.multiple) list.setAttribute('aria-multiselectable', 'true');
  pop.append(note, list);
  const live = el('div', 'kit-cb-live'); live.setAttribute('role', 'status'); live.setAttribute('aria-live', 'polite');
  root.append(field, pop, live); host.append(root);

  const query = () => typed ? input.value.trim() : '';
  const say = t => { live.textContent = t; };
  const emit = () => o.onChange && o.onChange(o.multiple ? sel.slice() : sel.length ? sel[0] : null, sel.map(v => known.get(v)));
  const refresh = () => o.source ? load(query()) : paint();

  function paintSel() {
    root.classList.toggle('kit-cb-has', sel.length > 0);
    if (!o.multiple) { input.value = sel.length ? known.get(sel[0]).label : ''; return; }
    field.querySelectorAll('.kit-cb-chip').forEach(c => c.remove());
    sel.forEach(v => {
      const it = known.get(v), c = el('span', 'kit-cb-chip'), x = btn('kit-cb-x', '×', T.remove(it.label));
      x.dataset.v = v; c.append(el('span', 'kit-cb-chip-t', it.label), x); field.insertBefore(c, input);
    });
  }
  function opt(it, i, q) {
    const e = el('div', 'kit-cb-opt'); e.id = id + '-o' + i; e.dataset.i = i; e.setAttribute('role', 'option');
    const on = !it.created && sel.includes(it.value);
    if (on) e.classList.add('kit-cb-on');
    e.setAttribute('aria-selected', String(o.multiple && on)); // multiple: chosen; single: the active option, set in setAct
    if (it.disabled) e.setAttribute('aria-disabled', 'true');
    const t = el('span', 'kit-cb-t');
    if (it.created) { e.classList.add('kit-cb-create'); t.textContent = T.create(it.label); } else mark(t, it.label, q);
    e.append(t); if (it.hint && !it.created) e.append(el('span', 'kit-cb-hint', it.hint));
    return e;
  }
  function paint() {
    const q = query(), rows = o.source ? srcItems : rank(items, q), secs = [], by = new Map();
    rows.forEach(it => { const g = it.group || ''; let s = by.get(g); if (!s) { s = { g, rows: [] }; by.set(g, s); secs.push(s); } s.rows.push(it); });
    shown = secs.flatMap(s => s.rows);
    const make = o.allowCreate && q && !shown.some(it => fold(it.label) === fold(q));
    if (make) shown.push({ value: q, label: q, created: true });
    list.replaceChildren(); let n = 0;
    secs.forEach((s, gi) => {
      let box = list;
      if (s.g) {
        box = el('div'); box.setAttribute('role', 'group'); const h = el('div', 'kit-cb-grp', s.g); h.id = id + '-g' + gi;
        box.setAttribute('aria-labelledby', h.id); box.append(h); list.append(box);
      }
      s.rows.forEach(it => box.append(opt(it, n++, q)));
    });
    if (make) list.append(opt(shown[n], n, q));
    const real = shown.length - (make ? 1 : 0), msg = failed && !loading ? T.error : !real ? (loading ? T.loading : T.empty) : '';
    note.textContent = msg; note.hidden = !msg || (make && !failed && !loading);
    note.classList.toggle('kit-cb-err', failed && !loading);
    list.setAttribute('aria-busy', String(loading)); pop.classList.toggle('kit-cb-busy', loading && real > 0);
    const w = want, j = w == null ? -1 : shown.findIndex(it => it.value === w);
    if (!loading) want = null;
    const ok = shown.findIndex(it => !it.disabled), cur = o.multiple ? -1 : shown.findIndex(it => sel.includes(it.value) && !it.disabled);
    setAct(j >= 0 ? j : typed ? ok : cur >= 0 ? cur : nav > 0 ? ok : nav < 0 ? shown.length - 1 : -1);
    say(loading ? T.loading : real ? T.count(real) : T.empty);
  }
  function setAct(i, scroll = true) {
    const prev = list.querySelector('.kit-cb-act');
    if (prev) { prev.classList.remove('kit-cb-act'); if (!o.multiple) prev.setAttribute('aria-selected', 'false'); }
    act = i;
    const e = i >= 0 && list.querySelector('[data-i="' + i + '"]');
    if (!e) { input.removeAttribute('aria-activedescendant'); return; }
    e.classList.add('kit-cb-act'); if (!o.multiple) e.setAttribute('aria-selected', 'true'); input.setAttribute('aria-activedescendant', e.id);
    if (!scroll) return;
    const top = e.offsetTop, bot = top + e.offsetHeight;
    if (i === 0 || top < pop.scrollTop) pop.scrollTop = i === 0 ? 0 : top; else if (bot > pop.scrollTop + pop.clientHeight) pop.scrollTop = bot - pop.clientHeight;
  }
  function step(d) {
    const n = shown.length; let i = act < 0 && d < 0 ? 0 : act;
    for (let k = 0; k < n; k++) { i = (i + d + n) % n; if (!shown[i].disabled) { setAct(i); return; } }
  }
  function place() {
    const r = root.getBoundingClientRect(), below = innerHeight - r.bottom, up = below < 240 && r.top > below;
    pop.classList.toggle('kit-cb-up', up); pop.style.maxHeight = Math.max(120, Math.min(300, (up ? r.top : below) - 12)) + 'px';
  }
  function abortLoad() { if (ctl) { ctl.abort(); ctl = null; } }
  function load(q) {
    clearTimeout(timer); abortLoad();
    const c = ctl = new AbortController(); loading = true; failed = false; paint();
    Promise.resolve().then(() => o.source(q, { signal: c.signal })).then(res => {
      if (c.signal.aborted) return;
      ctl = null; srcItems = reg(res || []); loading = false; paint();
    }, () => { if (c.signal.aborted) return; ctl = null; srcItems = []; loading = false; failed = true; paint(); });
  }
  function open(wait) {
    if (isOpen) return;
    isOpen = true; pop.hidden = false; root.classList.add('kit-cb-open'); input.setAttribute('aria-expanded', 'true'); place();
    if (o.source && !wait) load(query()); else paint();
  }
  function close() {
    if (!isOpen) return;
    isOpen = false; clearTimeout(timer); abortLoad(); loading = false; failed = false; want = null; nav = 0; pop.hidden = true;
    root.classList.remove('kit-cb-open'); input.setAttribute('aria-expanded', 'false'); input.removeAttribute('aria-activedescendant'); say('');
    typed = false; paintSel(); if (o.multiple) input.value = '';
  }
  function drop(v) {
    const it = known.get(v); sel = sel.filter(x => x !== v); paintSel(); say(T.removed(it.label)); emit(); if (isOpen) refresh();
  }
  function pick(i) {
    const it = shown[i]; if (!it || it.disabled) return;
    const v = it.value, had = sel.includes(v); known.set(v, it);
    if (!o.multiple) { sel = [v]; close(); if (!had) emit(); return; }
    sel = had ? sel.filter(x => x !== v) : [...sel, v]; typed = false; input.value = ''; paintSel(); want = v; refresh(); say(had ? T.removed(it.label) : T.added(it.label)); emit();
  }

  on(input, 'input', () => {
    typed = true;
    if (!o.multiple && !input.value && sel.length) { sel = []; paintSel(); typed = true; emit(); }
    open(true);
    if (!o.source) { paint(); return; }
    clearTimeout(timer); abortLoad(); loading = true; failed = false; paint();
    timer = setTimeout(() => load(query()), o.debounce);
  });
  on(input, 'keydown', e => {
    if (e.isComposing) return;
    const k = e.key;
    if (k === 'ArrowDown' || k === 'ArrowUp') {
      e.preventDefault();
      if (!isOpen) { nav = e.altKey ? 0 : k === 'ArrowDown' ? 1 : -1; open(); }
      else step(k === 'ArrowDown' ? 1 : -1);
    } else if (k === 'Enter') { if (isOpen && (act >= 0 || loading)) { e.preventDefault(); if (!loading) pick(act); } }
    else if (k === 'Escape') { if (isOpen) { e.preventDefault(); e.stopPropagation(); close(); } }
    else if (o.multiple && !input.value && sel.length) {
      if (k === 'Backspace') { e.preventDefault(); drop(sel[sel.length - 1]); }
      else if (k === 'ArrowLeft' && input.selectionStart === 0) { e.preventDefault(); close(); [...field.querySelectorAll('.kit-cb-x')].pop().focus(); }
    }
    if (isOpen && (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'Home' || k === 'End')) setAct(-1); // focus is back in the text
  });
  on(input, 'click', () => { if (!o.multiple && !isOpen) input.select(); open(); });
  on(field, 'mousedown', e => { if (e.target.closest('button')) e.preventDefault(); });
  on(field, 'click', e => {
    const x = e.target.closest('.kit-cb-x'), b = e.target.closest('button');
    if (x) { drop(x.dataset.v); input.focus(); }
    else if (b === clear) { sel = []; paintSel(); emit(); input.focus(); if (isOpen) refresh(); }
    else if (b === chev) { if (isOpen) close(); else { input.focus(); open(); } }
    else if (!b && e.target !== input) { input.focus(); open(); }
  });
  on(field, 'keydown', e => {
    const x = e.target.closest && e.target.closest('.kit-cb-x'); if (!x) return;
    const all = [...field.querySelectorAll('.kit-cb-x')], i = all.indexOf(x), back = e.key === 'Backspace';
    if (e.key === 'ArrowLeft') { e.preventDefault(); (all[i - 1] || x).focus(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); (all[i + 1] || input).focus(); }
    else if (back || e.key === 'Delete') { e.preventDefault(); drop(x.dataset.v); (field.querySelectorAll('.kit-cb-x')[back ? i - 1 : i] || input).focus(); }
  });
  on(list, 'click', e => { const r = e.target.closest('.kit-cb-opt'); if (r) pick(+r.dataset.i); });
  on(list, 'pointermove', e => {
    const p = e.clientX + ',' + e.clientY, r = e.target.closest('.kit-cb-opt');
    if (p === xy || e.pointerType === 'touch') return; xy = p;
    if (r && +r.dataset.i !== act) setAct(+r.dataset.i, false);
  });
  on(pop, 'mousedown', e => e.preventDefault());
  on(root, 'focusout', e => {
    if (root.contains(e.relatedTarget)) return;
    const it = shown[act]; // automatic selection: leaving with a match highlighted and text typed accepts it (single choice)
    if (isOpen && !o.multiple && typed && !loading && input.value.trim() && it && !it.created && !it.disabled) pick(act); else close();
  });

  function setValue(v) {
    const a = v == null ? [] : Array.isArray(v) ? v : [v];
    sel = a.map(x => { const it = x && typeof x === 'object' ? norm(x) : known.get(String(x)) || norm(x); known.set(it.value, it); return it.value; }).slice(0, o.multiple ? a.length : 1);
    typed = false; paintSel(); if (isOpen) refresh();
  }
  setValue(o.value);

  return {
    el: root, input,
    getValue: () => o.multiple ? sel.slice() : sel.length ? sel[0] : null,
    getItems: () => sel.map(v => known.get(v)),
    setValue,
    setItems(l) { items = reg(l || []); if (isOpen && !o.source) paint(); },
    open: () => { open(); }, close, focus: () => input.focus(),
