    const source = c.source && ((q, { signal }) => new Promise((res, rej) => {
      setNet(n => ({ ...n, asked: n.asked + 1 }));
      const stop = () => { clearTimeout(t); setNet(n => ({ ...n, cancelled: n.cancelled + 1 })); rej(new DOMException('Aborted', 'AbortError')); };
