        ${c.source ? html`<p class="pv-label">${net.asked} requests asked, ${net.cancelled} cancelled before they answered</p>
          <button type="button" class=${'pv-btn' + (down ? ' pri' : '')} aria-pressed=${down} onClick=${() => { offline.current = !down; setDown(!down); }}>Service offline</button>` : ''}
        <p><button type="button" class="pv-btn" onClick=${() => box.current && box.current.setValue(c.value)}>setValue(start)</button></p>
      </section>
    </div></div>`;
